<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';require __DIR__.'/oven_lib.php';
$uid=auth();$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();try {
  $action=(string)($_POST['action']??'save');
  if($action==='save'){
   $dims=lab_oven_diameter(number($_POST['ns']??null,12,600,'north–south span'),number($_POST['ew']??null,12,600,'east–west span'));
   $height=number($_POST['height']??null,6,240,'internal height');
   $fx=number($_POST['fire_x']??null,0,1,'fire X');$fy=number($_POST['fire_y']??null,0,1,'fire Y');
   if(!lab_ellipse_inside($fx,$fy))throw new RuntimeException('Fire location must be within the oven floor.');
   $zones=lab_oven_zones(json_decode((string)($_POST['zones_json']??'[]'),true,32,JSON_THROW_ON_ERROR));
   $name=plain($_POST['name']??'',140);if($name==='')throw new RuntimeException('Enter an oven name.');
   $id=(int)($_POST['id']??0);
   if($id>0){if(!query('SELECT id FROM oven_layouts WHERE id=?',[$id])->fetch())throw new RuntimeException('Oven not found.');query('UPDATE oven_layouts SET name=?,north_south_in=?,east_west_in=?,internal_height_in=?,fire_x=?,fire_y=?,zones_json=?,updated_by_user_id=? WHERE id=?',[$name,$dims['north_south_in'],$dims['east_west_in'],$height,$fx,$fy,json_encode($zones),$uid,$id]);}
   else {query('INSERT INTO oven_layouts (name,north_south_in,east_west_in,internal_height_in,fire_x,fire_y,zones_json,created_by_user_id,updated_by_user_id) VALUES (?,?,?,?,?,?,?,?,?)',[$name,$dims['north_south_in'],$dims['east_west_in'],$height,$fx,$fy,json_encode($zones),$uid,$uid]);$id=(int)db()->lastInsertId();}
   header('Location: oven_layout.php?id='.$id.'&saved=1');exit;
  }elseif($action==='reading'){
   $id=(int)($_POST['id']??0);$oven=query('SELECT * FROM oven_layouts WHERE id=?',[$id])->fetch();if(!$oven)throw new RuntimeException('Oven not found.');
   $zones=lab_oven_zones(json_decode($oven['zones_json'],true,32,JSON_THROW_ON_ERROR));$keys=array_column($zones,'key');$key=(string)($_POST['zone_key']??'');if(!in_array($key,$keys,true))throw new RuntimeException('Temperature zone not found.');
   query('INSERT INTO oven_zone_readings (oven_layout_id,zone_key,stone_f,observed_at,recorded_by_user_id,notes) VALUES (?,?,?,NOW(),?,?)',[$id,$key,number($_POST['stone_f']??null,0,1500,'stone temperature'),$uid,plain($_POST['notes']??'',600)]);
   header('Location: oven_layout.php?id='.$id.'&reading=1');exit;
  }else throw new RuntimeException('Unsupported action.');
 }catch(Throwable $ex){$error=$ex->getMessage();}
}
$ovens=query('SELECT id,name FROM oven_layouts ORDER BY updated_at DESC LIMIT 60')->fetchAll();$id=isset($_GET['new'])?0:(int)($_GET['id']??($ovens[0]['id']??0));$oven=$id?query('SELECT * FROM oven_layouts WHERE id=?',[$id])->fetch():null;
$zones=$oven?json_decode($oven['zones_json'],true):[];$readings=$oven?query('SELECT r.*,u.display_name FROM oven_zone_readings r JOIN users u ON u.id=r.recorded_by_user_id WHERE oven_layout_id=? ORDER BY observed_at DESC,id DESC LIMIT 40',[$id])->fetchAll():[];
function h(string $t):string{return htmlspecialchars($t,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Oven Floor · Pizza Lab</title><link rel="stylesheet" href="assets/style.css?v=1.5.5"><style>.ovenmap{width:100%;max-height:550px;touch-action:none;border:1px solid #35424b;border-radius:14px;background:#111923}.ovenmap text{fill:#f7e4c9;font-size:13px}.ovenmap .hot{fill:#df7137}.ovenmap .zone{fill:#7fbe9c;stroke:#e4ffef;stroke-width:2;cursor:move}.zone-row{display:grid;grid-template-columns:1.5fr .7fr .7fr auto;gap:8px;align-items:end;margin:8px 0}</style></head><body><main class="view" style="max-width:1250px"><p><a href="index.php">← Pizza Lab</a> · <a href="heatmap.php">Cooking heat map →</a></p><h1>Desktop Oven Layout Builder</h1><p class="muted">Measure north–south and east–west floor spans and the inside height. Drag the fire and temperature-zone markers. Heat is entered from your IR thermometer, never inferred from camera imagery.</p><?php if($error):?><p class="danger"><?=h($error)?></p><?php endif;?><?php if(isset($_GET['saved'])||isset($_GET['reading'])):?><p class="notice-strip">Changes saved.</p><?php endif;?><div class="flex mb"><label>Existing oven<select id="ovenChoose"><option value="">New oven layout</option><?php foreach($ovens as $o):?><option value="<?=$o['id']?>" <?=$id===$o['id']?'selected':''?>><?=h($o['name'])?></option><?php endforeach;?></select></label><button id="newOven">+ New oven</button></div><div class="grid-2"><form method="post" class="panel stack" id="ovenForm"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" id="layoutId" value="<?=h((string)($oven['id']??''))?>"><label>Oven name<input name="name" id="ovenName" required maxlength="140" value="<?=h($oven['name']??'Wood-fired oven')?>"></label><div class="three"><label>North–South (in)<input id="ns" name="ns" type="number" step=".25" min="12" max="600" value="<?=h((string)($oven['north_south_in']??72))?>"></label><label>East–West (in)<input id="ew" name="ew" type="number" step=".25" min="12" max="600" value="<?=h((string)($oven['east_west_in']??72))?>"></label><label>Inside height (in)<input id="height" name="height" type="number" step=".25" min="6" max="240" value="<?=h((string)($oven['internal_height_in']??18))?>"></label></div><div class="two"><label>Fire position West→East 0–1<input id="fireX" name="fire_x" type="number" step=".01" min="0" max="1" value="<?=h((string)($oven['fire_x']??.78))?>"></label><label>Fire position North→South 0–1<input id="fireY" name="fire_y" type="number" step=".01" min="0" max="1" value="<?=h((string)($oven['fire_y']??.48))?>"></label></div><p class="small" id="floorStats"></p><h2>Temperature zones</h2><div id="zoneRows"></div><button type="button" id="addZone">+ Add temperature zone</button><input type="hidden" id="zonesJson" name="zones_json"><button type="submit" class="primary">Save oven layout</button></form><div class="panel stack"><h2>Floor plan · top-down</h2><svg id="ovenCanvas" class="ovenmap" viewBox="0 0 660 500" role="img" aria-label="Editable elliptical oven layout"><ellipse cx="330" cy="240" rx="275" ry="202" fill="#29333b" stroke="#9b9d92" stroke-width="4"/><ellipse id="innerCircle" cx="330" cy="240" rx="201" ry="201" fill="none" stroke="#e3bd81" stroke-dasharray="5 8"/><text x="330" y="22" text-anchor="middle">NORTH</text><text x="330" y="489" text-anchor="middle">SOUTH / ENTRANCE</text><text x="22" y="244">W</text><text x="626" y="244">E</text><g id="mapMarkers"></g></svg><p class="small">Drag the fire or zone dots inside the floor outline. The dashed circle represents the largest centered circular footprint, not the exact floor if it is oval.</p><?php if($oven):?><form method="post" class="stack"><h3>Log actual zone temperature</h3><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="reading"><input type="hidden" name="id" value="<?=$oven['id']?>"><label>Zone<select name="zone_key" required><?php foreach($zones as $z):?><option value="<?=h($z['key'])?>"><?=h($z['name'])?></option><?php endforeach;?></select></label><label>IR stone °F<input type="number" name="stone_f" min="0" max="1500" step=".1" required></label><label>Notes<input name="notes" maxlength="600"></label><button>Record measured temperature</button></form><?php endif;?></div></div><?php if($readings):?><section class="panel mt"><h2>Recent heat-gun readings</h2><table class="compact-table"><thead><tr><th>Time</th><th>Zone</th><th>°F</th><th>Recorded by</th></tr></thead><tbody><?php foreach($readings as $r):?><tr><td><?=h($r['observed_at'])?></td><td><?=h($r['zone_key'])?></td><td><?=h($r['stone_f'])?></td><td><?=h($r['display_name'])?></td></tr><?php endforeach;?></tbody></table></section><?php endif;?></main><script>window.START_ZONES=<?=json_encode($zones,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;</script><script defer src="assets/oven_layout.js?v=1.5.5"></script></body></html>
